"use client"

import * as React from "react"
import { cn } from "cn"
import { TextArea } from "react-aria-components"

/** value.json: a minimal ProseMirror-shaped document. */
type RichNode = {
  type: "doc" | "paragraph" | "heading" | "bulletList" | "orderedList" | "listItem" | "blockquote" | "codeBlock" | "text" | "hardBreak"
  attrs?: { level?: 1 | 2 | 3 | 4 }
  text?: string
  marks?: { type: "bold" | "italic" | "code" | "link"; attrs?: { href?: string } }[]
  content?: RichNode[]
}

const proseClassName =
  "max-w-prose text-base leading-7 text-foreground [&_a]:text-primary [&_a]:underline [&_a]:underline-offset-4 [&_blockquote]:border-l-2 [&_blockquote]:border-border [&_blockquote]:pl-4 [&_blockquote]:text-muted-foreground [&_code]:rounded-sm [&_code]:bg-muted [&_code]:px-1 [&_code]:font-mono [&_code]:text-[0.9em] [&_h1]:font-heading [&_h1]:text-3xl [&_h1]:font-semibold [&_h2]:font-heading [&_h2]:text-2xl [&_h2]:font-semibold [&_h3]:font-heading [&_h3]:text-xl [&_h3]:font-semibold [&_ol]:list-decimal [&_ol]:pl-6 [&_pre]:overflow-x-auto [&_pre]:rounded-lg [&_pre]:bg-muted [&_pre]:p-4 [&_ul]:list-disc [&_ul]:pl-6 [&>*+*]:mt-4"

function inline(text: string, key: string): React.ReactNode[] {
  const out: React.ReactNode[] = []
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*|`[^`]+`|\[[^\]]+\]\([^)\s]+\))/g
  let last = 0
  let m: RegExpExecArray | null
  let i = 0
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(text.slice(last, m.index))
    const t = m[0]
    const k = `${key}-${i++}`
    if (t.startsWith("**")) out.push(<strong key={k}>{t.slice(2, -2)}</strong>)
    else if (t.startsWith("`")) out.push(<code key={k}>{t.slice(1, -1)}</code>)
    else if (t.startsWith("[")) {
      const [, label, href] = /^\[([^\]]+)\]\(([^)\s]+)\)$/.exec(t) ?? []
      out.push(<a key={k} href={href}>{label}</a>)
    } else out.push(<em key={k}>{t.slice(1, -1)}</em>)
    last = m.index + t.length
  }
  if (last < text.length) out.push(text.slice(last))
  return out
}

/** value.markdown: block subset (headings, paragraphs, lists, quotes, fenced code). */
function fromMarkdown(md: string): React.ReactNode[] {
  const blocks = md.replace(/\r\n/g, "\n").split(/\n{2,}/)
  return blocks.map((block, b) => {
    const key = `b${b}`
    const lines = block.split("\n")
    const heading = /^(#{1,4})\s+(.*)$/.exec(block)
    if (block.startsWith("```")) return <pre key={key}><code>{lines.slice(1, lines.at(-1) === "```" ? -1 : undefined).join("\n")}</code></pre>
    if (heading) return React.createElement(`h${heading[1].length}`, { key }, inline(heading[2], key))
    if (lines.every((l) => /^[-*]\s/.test(l))) return <ul key={key}>{lines.map((l, i) => <li key={i}>{inline(l.slice(2), `${key}-${i}`)}</li>)}</ul>
    if (lines.every((l) => /^\d+\.\s/.test(l))) return <ol key={key}>{lines.map((l, i) => <li key={i}>{inline(l.replace(/^\d+\.\s/, ""), `${key}-${i}`)}</li>)}</ol>
    if (lines.every((l) => l.startsWith(">"))) return <blockquote key={key}>{inline(lines.map((l) => l.replace(/^>\s?/, "")).join(" "), key)}</blockquote>
    return <p key={key}>{inline(lines.join(" "), key)}</p>
  })
}

function fromJson(node: RichNode, key = "n"): React.ReactNode {
  const kids = node.content?.map((c, i) => fromJson(c, `${key}-${i}`))
  switch (node.type) {
    case "doc": return <React.Fragment key={key}>{kids}</React.Fragment>
    case "paragraph": return <p key={key}>{kids}</p>
    case "heading": return React.createElement(`h${node.attrs?.level ?? 2}`, { key }, kids)
    case "bulletList": return <ul key={key}>{kids}</ul>
    case "orderedList": return <ol key={key}>{kids}</ol>
    case "listItem": return <li key={key}>{kids}</li>
    case "blockquote": return <blockquote key={key}>{kids}</blockquote>
    case "codeBlock": return <pre key={key}><code>{node.content?.map((c) => c.text).join("")}</code></pre>
    case "hardBreak": return <br key={key} />
    case "text": {
      let el: React.ReactNode = node.text
      for (const mark of node.marks ?? []) {
        if (mark.type === "bold") el = <strong>{el}</strong>
        else if (mark.type === "italic") el = <em>{el}</em>
        else if (mark.type === "code") el = <code>{el}</code>
        else if (mark.type === "link") el = <a href={mark.attrs?.href}>{el}</a>
      }
      return <React.Fragment key={key}>{el}</React.Fragment>
    }
  }
}

/**
 * Rich text. state.read-only renders value.markdown or value.json as prose;
 * state.editable shows a React Aria TextArea over the markdown source.
 */
function RichText({
  value,
  editable = false,
  onChange,
  label = "Rich text",
  className,
}: {
  value: string | RichNode
  editable?: boolean
  onChange?: (markdown: string) => void
  label?: string
  className?: string
}) {
  if (editable && typeof value === "string") {
    return (
      <TextArea
        data-slot="rich-text"
        data-state="editable"
        aria-label={label}
        value={value}
        onChange={(e) => onChange?.(e.target.value)}
        className={cn(
          "min-h-40 w-full rounded-lg border border-input bg-transparent px-3 py-2 font-mono text-sm outline-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 dark:bg-input/30",
          className
        )}
      />
    )
  }
  return (
    <div data-slot="rich-text" data-state="read-only" className={cn(proseClassName, className)}>
      {typeof value === "string" ? fromMarkdown(value) : fromJson(value)}
    </div>
  )
}

export { RichText, type RichNode }
